css:
/* castle-design for ircord: the shape tokens of castle.css, and glass over the castle. Colours come from the theme's seeds (light and dark), because a theme's CSS cannot switch on the mode. */
:root {
  --radius: 10px;
  --radius-large: 16px;
  --font-ui: system-ui, -apple-system, "Segoe UI", Roboto, "Noto Sans", sans-serif;
  --font-mono: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
}
/* With the castle picture as the background (the web client's studio), the picture is stronger and the panels are frosted glass over it, as in the castle apps. Without a background these rules match nothing. */
:root[data-theme-background='app'] .workspace::before {
  opacity: 0.7;
}
:root[data-theme-background='app'] .chat-main {
  background-color: color-mix(in srgb, var(--main) 55%, transparent);
  -webkit-backdrop-filter: blur(10px);
  backdrop-filter: blur(10px);
}
@media (min-width: 900px) {
  :root[data-theme-background='app'] .conversation-sidebar {
    background: color-mix(in srgb, var(--sidebar) 55%, transparent);
    -webkit-backdrop-filter: blur(10px);
    backdrop-filter: blur(10px);
  }
}
